3.1. ==task.json==&#123;    &quot;version&quot;: &quot;2.0.0&quot;,    &quot;tasks&quot;: [        &#123;            &quot;type&quot;: &quot;cppbuild&quot;,            &quot;label&quot;: &quot;C/C++: g++.exe 生成活动文件&quot;,            &quot;command&quot;: &quot;D:\\AppGallery\\Software\\mingw64\\bin\\g++.exe&quot;,            &quot;args&quot;: [                &quot;-fdiagnostics-color=always&quot;,                &quot;-g&quot;,                &quot;*.cpp&quot;,  // 编译所有 .cpp 文件                &quot;-o&quot;,                &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;            ],            &quot;options&quot;: &#123;                &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot;            &#125;,            &quot;problemMatcher&quot;: [&quot;$gcc&quot;],            &quot;group&quot;: &#123;                &quot;kind&quot;: &quot;build&quot;,                &quot;isDefault&quot;: true            &#125;        &#125;    ]&#125;
&#123;  &quot;version&quot;: &quot;2.0.0&quot;, // 指定任务配置文件的版本，2.0.0 是当前标准版本  &quot;tasks&quot;: [    &#123;      &quot;type&quot;: &quot;cppbuild&quot;, // 任务类型，标识这是一个 C++ 构建任务      &quot;label&quot;: &quot;C/C++: g++.exe 生成活动文件&quot;, // 任务的显示名称，在任务选择器中可见      &quot;command&quot;: &quot;D:\\AppGallery\\Software\\mingw64\\bin\\g++.exe&quot;, // 指定要执行的编译器路径（修改为新的 MinGW64 路径）      &quot;args&quot;: [ // 传递给编译器的命令行参数        &quot;-fdiagnostics-color=always&quot;, // 启用彩色错误输出        &quot;-g&quot;, // 生成调试信息        &quot;*.cpp&quot;, // 编译当前目录下所有 .cpp 文件        &quot;-o&quot;, // 指定输出文件        &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;, // 输出可执行文件的路径和名称        &quot;-lwinmm&quot; // 链接 Windows 多媒体库（用于音频、计时器等功能）      ],      &quot;options&quot;: &#123; // 任务执行的选项        &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot; // 设置工作目录为当前文件所在目录      &#125;,      &quot;problemMatcher&quot;: [ // 问题匹配器，用于解析编译器输出        &quot;$gcc&quot; // 使用内置的 GCC 问题匹配器      ],      &quot;group&quot;: &#123; // 任务分组信息        &quot;kind&quot;: &quot;build&quot;, // 将任务归类为构建任务        &quot;isDefault&quot;: true // 设为默认构        建任务，可通过快捷键运行      &#125;    &#125;  ]&#125;
3.2. ==launch.json==&#123;    &quot;version&quot;: &quot;0.2.0&quot;,    &quot;configurations&quot;: [        &#123;            &quot;name&quot;: &quot;(gdb) 启动&quot;,            &quot;type&quot;: &quot;cppdbg&quot;,            &quot;request&quot;: &quot;launch&quot;,            &quot;program&quot;: &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;,            &quot;args&quot;: [],            &quot;stopAtEntry&quot;: false,            &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot;,            &quot;environment&quot;: [],            &quot;externalConsole&quot;: true,            &quot;MIMode&quot;: &quot;gdb&quot;,            &quot;miDebuggerPath&quot;: &quot;D:\\MinGW\\bin\\gdb.exe&quot;,//gdb路径            &quot;setupCommands&quot;: [                &#123;                    &quot;description&quot;: &quot;为 gdb 启用整齐打印&quot;,                    &quot;text&quot;: &quot;-enable-pretty-printing&quot;,                    &quot;ignoreFailures&quot;: true                &#125;,                &#123;                    &quot;description&quot;: &quot;将反汇编风格设置为 Intel&quot;,                    &quot;text&quot;: &quot;-gdb-set disassembly-flavor intel&quot;,                    &quot;ignoreFailures&quot;: true                &#125;            ]        &#125;,        &#123;            &quot;name&quot;: &quot;C/C++: g++.exe 构建和调试活动文件&quot;,            &quot;type&quot;: &quot;cppdbg&quot;,            &quot;request&quot;: &quot;launch&quot;,            &quot;program&quot;: &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;,            &quot;args&quot;: [],            &quot;stopAtEntry&quot;: false,            &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot;,            &quot;environment&quot;: [],            &quot;externalConsole&quot;: true,            &quot;MIMode&quot;: &quot;gdb&quot;,            &quot;miDebuggerPath&quot;: &quot;D:\\AppGallery\\Software\\MinGW\\bin\\gdb.exe&quot;,            &quot;setupCommands&quot;: [                &#123;                    &quot;description&quot;: &quot;为 gdb 启用整齐打印&quot;,                    &quot;text&quot;: &quot;-enable-pretty-printing&quot;,                    &quot;ignoreFailures&quot;: true                &#125;,                &#123;                    &quot;description&quot;: &quot;将反汇编风格设置为 Intel&quot;,                    &quot;text&quot;: &quot;-gdb-set disassembly-flavor intel&quot;,                    &quot;ignoreFailures&quot;: true                &#125;            ],            &quot;preLaunchTask&quot;: &quot;C/C++: g++.exe 生成活动文件&quot;        &#125;    ]&#125;
&#123;  &quot;version&quot;: &quot;0.2.0&quot;, // 指定调试配置文件的版本  &quot;configurations&quot;: [    &#123;      &quot;name&quot;: &quot;(gdb) 启动&quot;, // 调试配置的显示名称      &quot;type&quot;: &quot;cppdbg&quot;, // 调试器类型，cppdbg 是 C/C++ 扩展的调试器      &quot;request&quot;: &quot;launch&quot;, // 请求类型，launch 表示启动程序进行调试      &quot;program&quot;: &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;, // 要调试的可执行文件路径      &quot;args&quot;: [], // 传递给程序的命令行参数（此处为空）      &quot;stopAtEntry&quot;: false, // 是否在程序入口点停止（false 表示不暂停）      &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot;, // 程序运行时的当前工作目录      &quot;environment&quot;: [], // 程序运行时的环境变量（此处为空）      &quot;externalConsole&quot;: true, // 是否在外部控制台窗口运行程序      &quot;MIMode&quot;: &quot;gdb&quot;, // 调试器模式，使用 GDB      &quot;miDebuggerPath&quot;: &quot;D:\\MinGW\\bin\\gdb.exe&quot;, // GDB 调试器的路径      &quot;setupCommands&quot;: [ // 调试器启动时执行的设置命令        &#123;          &quot;description&quot;: &quot;为 gdb 启用整齐打印&quot;, // 命令描述          &quot;text&quot;: &quot;-enable-pretty-printing&quot;, // 启用 GDB 的格式化输出          &quot;ignoreFailures&quot;: true // 如果命令失败是否忽略        &#125;,        &#123;          &quot;description&quot;: &quot;将反汇编风格设置为 Intel&quot;, // 命令描述          &quot;text&quot;: &quot;-gdb-set disassembly-flavor intel&quot;, // 设置反汇编为 Intel 风格（而非 AT&amp;T 风格）          &quot;ignoreFailures&quot;: true // 如果命令失败是否忽略        &#125;      ]    &#125;,    &#123;      &quot;name&quot;: &quot;C/C++: g++.exe 构建和调试活动文件&quot;, // 第二个调试配置的名称      &quot;type&quot;: &quot;cppdbg&quot;, // 调试器类型      &quot;request&quot;: &quot;launch&quot;, // 请求类型      &quot;program&quot;: &quot;$&#123;fileDirname&#125;\\$&#123;fileBasenameNoExtension&#125;.exe&quot;, // 要调试的可执行文件路径      &quot;args&quot;: [], // 传递给程序的命令行参数（此处为空）      &quot;stopAtEntry&quot;: false, // 是否在程序入口点停止      &quot;cwd&quot;: &quot;$&#123;fileDirname&#125;&quot;, // 程序运行时的当前工作目录      &quot;environment&quot;: [], // 程序运行时的环境变量（此处为空）      &quot;externalConsole&quot;: true, // 是否在外部控制台窗口运行程序      &quot;MIMode&quot;: &quot;gdb&quot;, // 调试器模式，使用 GDB      &quot;miDebuggerPath&quot;: &quot;D:\\AppGallery\\Software\\MinGW\\bin\\gdb.exe&quot;, // GDB 调试器的路径（更新为新的路径）      &quot;setupCommands&quot;: [ // 调试器启动时执行的设置命令        &#123;          &quot;description&quot;: &quot;为 gdb 启用整齐打印&quot;, // 命令描述          &quot;text&quot;: &quot;-enable-pretty-printing&quot;, // 启用 GDB 的格式化输出          &quot;ignoreFailures&quot;: true // 如果命令失败是否忽略        &#125;,        &#123;          &quot;description&quot;: &quot;将反汇编风格设置为 Intel&quot;, // 命令描述          &quot;text&quot;: &quot;-gdb-set disassembly-flavor intel&quot;, // 设置反汇编为 Intel 风格          &quot;ignoreFailures&quot;: true // 如果命令失败是否忽略        &#125;      ],      &quot;preLaunchTask&quot;: &quot;C/C++: g++.exe 生成活动文件&quot; // 调试前执行的任务（会先编译代码）    &#125;  ]&#125;

