DELETE FROM 订单WHERE 客户ID = (SELECT 客户ID FROM 客户 WHERE 公司名称 = &#x27;东南实业&#x27;);DELETE FROM 订单WHERE 客户ID = (SELECT 客户ID FROM 客户 WHERE 公司名称 = &#x27;三川实业有限公司&#x27;);
